"""Small plain-text synthetic acceptance report renderer."""
from datetime import datetime,timezone

def render(audit,manifest,*,runtime,elapsed_seconds,workspace_bytes):
 lines=['# Synthetic package preparation report','',f"Status: {audit.get('status','NOT_RUN')}",'','This is a deterministic synthetic fixture run only. No market data was downloaded, transformed, or evaluated; no performance claim is made. August validation was not run.','',f"- Runtime: {runtime.get('version')} ({runtime.get('executable')})",f"- Run ID: {manifest.get('run_id')}",f"- Settings: {manifest.get('settings')}; candidate cells: {manifest.get('candidate_cells')}; candidate summary rows: {manifest.get('candidate_summary_rows')}; control rows: {manifest.get('baseline_summary_rows')}; total rows: {manifest.get('summary_rows')}",f"- Zero-result rows preserved: {audit.get('zero_rows')}",f"- Independent indicator checks: {audit.get('independent_indicator_checks')}",f"- Minute barrier checks: {audit.get('barrier_checks')}",f"- Causal prefix positions: {audit.get('causal_prefix_checks')}; candidate mask comparisons: {audit.get('causal_mask_comparisons')}",f"- Independent raw summary rebuild: {audit.get('status')}",f"- Elapsed seconds to report: {elapsed_seconds:.3f}",f"- Whole workspace bytes (measured): {workspace_bytes}",'','## Scope notes','','- Three assets: BTC, ETH, SOL; three fixed exclusive labels: BREAKOUT, PULLBACK, TURN. PULLBACK uses EMA context and TURN uses RSI; classifier overlap with those families is disclosed.','- 226 single-indicator settings are evaluated across 2,034 asset/state candidates and two synthetic outcome horizons.','- Complete grid retained: 4,068 candidate rows plus 36 controls = 4,104. A zero-alert row remains present with null precision/Wilson values where n=0.','- All fixture alerts and outcomes are synthetic. The exercise validates plumbing and declared calculations only; it does not estimate market performance, significance, or future returns.','- Data sourcing is not exercised. The market-source contract is metadata only; no local/remote market file was opened.','',f"Generated at {datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')} UTC."]
 return '\n'.join(lines)+'\n'
